Минимальный пример “диагностики проекта” на Python:
```py
import os
import json
import hashlib

TEXT_EXT = {'.py','.js','.ts','.html','.css','.json','.md'}
SKIP_DIRS = {'node_modules','.git','dist','build','__pycache__','.venv','venv'}
MAX_FILE_BYTES = 200_000   # чтобы не тащить огромные файлы
MAX_FILES = 500

def read_text_safe(path):
    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            return f.read()
    except Exception as e:
        return None

def diagnose_project(root):
    report = {
        "root": os.path.abspath(root),
        "files": [],
        "errors": [],
        "stats": {"total_files": 0, "included": 0, "skipped": 0}
    }

    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS]

        for name in filenames:
            report["stats"]["total_files"] += 1
            full = os.path.join(dirpath, name)
            ext = os.path.splitext(name)[1].lower()

            if ext not in TEXT_EXT:
                report["stats"]["skipped"] += 1
                continue

            try:
                size = os.path.getsize(full)
                if size > MAX_FILE_BYTES:
                    report["files"].append({
                        "path": os.path.relpath(full, root),
                        "size": size,
                        "skipped_reason": "too_large"
                    })
                    report["stats"]["skipped"] += 1
                    continue

                content = read_text_safe(full)
                if content is None:
                    report["errors"].append({"path": os.path.relpath(full, root), "error": "read_failed"})
                    continue

                sha = hashlib.sha256(content.encode('utf-8', errors='replace')).hexdigest()

                # простые эвристики
                issues = []
                if '<<<<<<<' in content and '>>>>>>>' in content:
                    issues.append('merge_conflict_markers')
                if 'TODO' in content:
                    issues.append('todo_present')

                report["files"].append({
                    "path": os.path.relpath(full, root),
                    "size": size,
                    "sha256": sha,
                    "issues": issues,
                    "preview": content[:2000]  # ограниченный превью
                })
                report["stats"]["included"] += 1

                if report["stats"]["included"] >= MAX_FILES:
                    report["errors"].append({"error": "max_files_limit_reached"})
                    return report

            except Exception as e:
                report["errors"].append({"path": os.path.relpath(full, root), "error": str(e)})

    return report

if __name__ == '__main__':
    root = r'PUT_YOUR_PATH_HERE'
    rep = diagnose_project(root)
    print(json.dumps(rep, ensure_ascii=False, indent=2))
```

