## 3) JS: управление сессиями
Вставь в `index.js` (адаптируй под свои id):
```js
let sessions = JSON.parse(localStorage.getItem('chat_sessions') || '[]');
let currentChatId = null;

function uid() {
  return 'chat_' + Date.now() + '_' + Math.random().toString(16).slice(2);
}

function saveSessions() {
  localStorage.setItem('chat_sessions', JSON.stringify(sessions));
}

function loadMessages(chatId) {
  return JSON.parse(localStorage.getItem(`chat_messages:${chatId}`) || '[]');
}

function saveMessages(chatId, msgs) {
  localStorage.setItem(`chat_messages:${chatId}`, JSON.stringify(msgs));
}

function setCurrentChat(chatId) {
  currentChatId = chatId;
  messages = loadMessages(chatId);
  renderChat();
  renderChatList();
}

function createNewChat() {
  const id = uid();
  const session = {
    id,
    title: 'New chat',
    createdAt: Date.now(),
    updatedAt: Date.now()
  };
  sessions.unshift(session);
  saveSessions();
  saveMessages(id, []);
  setCurrentChat(id);
}

function renderChatList() {
  const list = document.getElementById('chat_list');
  if (!list) return;

  list.innerHTML = '';
  sessions
    .sort((a,b) => b.updatedAt - a.updatedAt)
    .forEach(s => {
      const btn = document.createElement('button');
      btn.className = 'chat-item' + (s.id === currentChatId ? ' active' : '');
      btn.textContent = s.title;
      btn.onclick = () => setCurrentChat(s.id);
      list.appendChild(btn);
    });
}

// New chat button
const newBtn = document.getElementById('new_chat_btn');
if (newBtn) newBtn.addEventListener('click', createNewChat);

// ТВОЁ ТРЕБОВАНИЕ: при каждом открытии страницы/обновлении — новый чат
createNewChat();
```

